  if (v >> 256n !== 0n) throw new Error('integer exceeds 32 bytes');
  const out = Buffer.alloc(32);
  let x = v;
  for (let i = 31; i >= 0; i--) {
    out[i] = Number(x & 0xffn);
    x >>= 8n;
