  assert.throws(
    () => wallet.submitTransaction(txSub({ to: '0x123' }), sigsFor('0x123' as any)),
    InvalidTransaction,
  );
  const good = actors(1)[0]!.address;
  assert.throws(
    () =>
      wallet.submitTransaction(
        txSub({ to: good, value: -1n }),
        signTransaction(ownerActors.slice(0, 2), {
          walletId: WALLET,
          nonce: 0n,
          deadline: 2000n,
          to: good,
          value: -1n,
