  for (; Rx < N + 1000n; Rx++) {
    const alpha = mod(Rx * Rx * Rx + 7n);
    const y = mod(modPow(alpha, (P + 1n) / 4n, P));
    if (mod(y * y) === alpha) {
      Ry = y;
      break;
    }
