  const s = 1n;
  const r = Rx - N; // 0 < r < N
  // Q = r^-1 (s R - e G)
  const sR: Pt = { x: Rx, y: Ry! };
  const eG = mul(e, { x: Gx, y: Gy });
  const negEG: Pt = eG ? { x: eG.x, y: mod(-eG.y) } : null;
  const sum = add(sR, negEG)!;
  const Q = mul(inv(r, N), sum)!;
  const expectedPub = Buffer.concat([Buffer.from([4]), toBytes(Q.x), toBytes(Q.y)]);

